export type ParsedDepositCollateralInstruction<
  TProgram extends string = typeof STOCK_VAULT_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    owner: TAccountMetas[0];
    market: TAccountMetas[1];
    position: TAccountMetas[2];
    collateralMint: TAccountMetas[3];
    ownerCollateral: TAccountMetas[4];
    collateralVault: TAccountMetas[5];
    collateralTokenProgram: TAccountMetas[6];
  };
  data: DepositCollateralInstructionData;
};

export function parseDepositCollateralInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedDepositCollateralInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 7,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      owner: getNextAccount(),
      market: getNextAccount(),
      position: getNextAccount(),
      collateralMint: getNextAccount(),
      ownerCollateral: getNextAccount(),
      collateralVault: getNextAccount(),
      collateralTokenProgram: getNextAccount(),
    },
    data: getDepositCollateralInstructionDataDecoder().decode(instruction.data),
  };
}
